 * out a ring of light), a stack of gift books, snow on the clouds and on the rail ties, a wreath on the pole, and the
 * near snow in front of the clouds. The reindeer tram that crosses the sky is page-wide
 * (template-parts/decor-christmas.php). Paths are drawn once in code and printed as fixed markup. Styles and
 * timeline: assets/css/season-christmas.css.
 *
 * @package ThuCac
 */

defined( 'ABSPATH' ) || exit;
// Near snow: one layer of flakes drawn twice one scene-height apart so the fall loops without a seam. Fixed seed:
// the same sky on every page view. Each flake sits on a cool glow (shown in Sáng only, where white snow on a pale
// sky needs it); the flake itself has a feathered edge and no rim.
$thu_cac_seed   = 20261225;
$thu_cac_rand   = static function () use ( &$thu_cac_seed ) {
	$thu_cac_seed = ( $thu_cac_seed * 1103515245 + 12345 ) % 2147483648;
	return $thu_cac_seed / 2147483648;
};
$thu_cac_flakes = static function ( $count, $min, $max ) use ( $thu_cac_rand ) {
	$out = '';
	for ( $i = 0; $i < $count; $i++ ) {
		$out .= sprintf( '<circle class="sc-flake-sh" cx="%1$.0F" cy="%2$.0F" r="%3$.1F"/><circle class="sc-flake" cx="%1$.0F" cy="%2$.0F" r="%3$.1F"/>', $thu_cac_rand() * 1440, $thu_cac_rand() * 720, $min + $thu_cac_rand() * ( $max - $min ) );
	}
	return $out;
};
// Aurora ribbons (Tối): a green curtain sweeping down from the top right, and an ice-blue one turning violet below it.
